custom_css:
/* Example CSS for your font: amazonember_lt */

/* Apply to all text */
:root * {
	--font-default: 'amazonember_lt';
	--default-font: 'amazonember_lt';
	--font-family-editor: 'amazonember_lt';
	--font-interface-override: 'amazonember_lt';
	--font-text-override: 'amazonember_lt';
}

/* Example: Apply to custom CSS class */
.custom-font * {
	font-family: 'amazonember_lt' !important;
}

/* Example: Apply to specific elements only */
.custom-font h1, .custom-font h2, .custom-font h3 {
	font-family: 'amazonember_lt' !important;
}
